import { Bot, BotController, WELCOME_INTENT_NAME } from 'umbot';
import { fullPlatforms } from 'umbot/plugins';
import { join } from 'node:path';

// A controller with the skill logic
class MyController extends BotController {
    public action(intentName: string | null): void {
        switch (intentName) {
            case WELCOME_INTENT_NAME:
                this.text = 'Hi! I am a new skill.';
                this.buttons.addBtn('Help');
                break;

            case 'help':
                this.text = 'I can answer commands and show buttons';
                break;

            default:
                this.text = this.userCommand || 'You did not say anything';
                break;
        }
    }
}

// Create the application
const bot = new Bot();
// Connect all available platforms
// If you only need voice platforms, use voicePlatforms, or a specific adapter if you need just one platform
bot.use(fullPlatforms);

// Configure commands
bot.setPlatformParams({
    intents: [
        {
            name: 'help',
            slots: ['help', 'what can you do'],
        },
    ],
});

// Configure the application
bot.setAppConfig({
    json: join(__dirname, 'data'),
    error_log: join(__dirname, 'logs'),
    isLocalStorage: true,
});

// Connect the controller
bot.initBotController(MyController);

bot.start('localhost', 3000);
```

