// 1. Create and register the plugin
const myCustomCachePlugin = createPlugin((appContext: AppContext) => {
    const cache = new Map<string, unknown>();

    // Register it under your own unique key.
    // The value must be either a function or an object with a getData method.
    appContext.plugins['myCustomCache'] = {
        getData(operation: unknown, key: unknown, value?: unknown): unknown {
            if (operation === 'set') {
                cache.set(String(key), value);
                return true;
            }
            if (operation === 'get') {
                return cache.get(String(key));
            }
            return undefined;
        },
    };
});

bot.use(myCustomCachePlugin);

// 2. Use it from your own code (for example, in a command or a controller)
bot.addCommand('save_data', ['save'], (text, controller) => {
    // Access the plugin through appContext.
    // The registry is typed with the generic AnyPluginData, so narrow the type to your implementation.
    const cache = controller.appContext.plugins['myCustomCache'] as
        { getData: (...args: unknown[]) => unknown } | undefined;
    if (cache) {
        cache.getData('set', 'last_command', text);
        controller.text = 'The data is saved in the custom cache!';
    }
});
