});

// The controller handles button presses
bot.initBotController(
    class extends BotController {
        action(intentName: string | null, isCommand?: boolean, isStep?: boolean): void {
            // Check the payload first — otherwise a collision: if the "Buy" button
            // matches the 'buy' command slot, the command fires, isCommand=true,
            // and we leave via the early return without reaching the payload.
            const data = this.payload as Record<string, unknown> | null;
            if (data?.action === 'buy') {
                this.text = `The purchase of product #${data.id} has been initiated.`;
                this.buttons.addBtn('Help');
                return;
            }

            // If a command/step fired, it has already done everything — exit.
            if (isCommand || isStep) return;

            // Regular handling by intentName (welcome, help, ...)
            this.buttons.addBtn('Help');
        }
    },
);
