// MyAdapter.ts
import { BasePlatformAdapter, TContent } from 'umbot/plugins';
import { BotController } from 'umbot';
import { Text } from 'umbot';

class MyAdapter extends BasePlatformAdapter {
    /**
     * The unique platform name
     */
    platformName: string = 'my_platform';

    /**
     * Returns whether the request belongs to the current platform
     * @param query - The request body
     * @param headers - The HTTP headers
     */
    isPlatformOnQuery(query: unknown, headers?: Record<string, unknown>): boolean {
        const q = query as Record<string, unknown>;
        return !!(q.data && (q.data as Record<string, unknown>).messageCount !== undefined);
    }

    /**
     * Processing the received request. In this method you need to fill the botController with the required data
     * @param query - The request from the platform
     * @param controller - The application controller
     */
    setQueryData(query: unknown, controller: BotController): boolean | Promise<boolean> {
        if (!query) {
            // write adapter errors through the context logger, not to console directly
            controller.appContext.logError('MyAdapter.setQueryData(): an empty request was sent');
            return false;
        }
        let content: Record<string, unknown>;
        if (typeof query === 'string') {
            content = JSON.parse(query);
        } else {
            content = query as Record<string, unknown>;
        }

        const data = content.data as Record<string, unknown> | undefined;

        controller.requestObject = content;
        controller.userId = content.userId as string;
        controller.userCommand = ((data?.text as string) || '').toLowerCase();
        controller.originalUserCommand = (data?.text as string) || '';
        controller.messageId = data?.messageCount as number;

        if (content.store) {
            controller.state = content.store as Record<string, unknown>;
        }

        controller.isScreen = false;

        return true;
    }

    /**
     * Returns the result that will be sent to the platform.
     * @param controller
     */
    getContent(controller: BotController): TContent {
        return {
            text: controller.text,
            tts: controller.tts,
        };
    }

    /**
     * Returns a demo request that the platform will send
     * @param query The user's request
     * @param userId The user ID
     * @param count The request sequence number
     * @param state Data from the local storage
     */
    getQueryExample(
        query: string,
        userId: string,
        count: number,
        state: Record<string, unknown> | string,
    ): Record<string, unknown> {
        return {
            userId,
            data: {
                text: query.toLowerCase(),
                messageCount: count,
            },
            store: state,
        };
    }
}
