// The parameters of a registered command
interface ICommandParam<TBotController extends BotController = BotController> {
    slots?: TSlots; // Activation triggers (strings or RegExp)
    isPattern?: boolean; // Interpret slots as RegExp
    cb: (
        userCommand: string,
        botController: TBotController,
    ) => void | string | Promise<void | string>;
