// src/index.ts
import { Bot, WELCOME_INTENT_NAME, HELP_INTENT_NAME, FALLBACK_COMMAND } from 'umbot';
import { fullPlatforms } from 'umbot/plugins';

const bot = new Bot()
    .use(fullPlatforms)
    .setAppConfig({ isLocalStorage: true })
    .setAppMode('strict_prod');

// The greeting command
bot.addCommand(WELCOME_INTENT_NAME, ['hello'], (_, bc) => {
    bc.text = 'Hi! I repeat after you. Say "help" or "bye".';
    bc.buttons.addBtn('Help');
});

// The "help" command
bot.addCommand(HELP_INTENT_NAME, ['help'], (_, bc) => {
    bc.text = 'I repeat after you. Say something, and I will repeat it.';
    bc.buttons.addBtn('Exit');
});

// Ending the dialog — isEnd = true closes the session.
// Supported by voice platforms (Alice, SmartApp, Marusia); chat platforms
// (Telegram, VK, Viber, MAX) do not read the flag — there the session ends by itself on a timeout.
bot.addCommand('bye', ['bye', 'exit', 'goodbye'], (_, bc) => {
    bc.text = 'Goodbye!';
    bc.isEnd = true;
});

// Fallback — repeat after the user everything that did not match the commands above.
bot.addCommand(FALLBACK_COMMAND, [], (userCommand, bc) => {
    bc.text = `You said: ${userCommand}`;
    bc.buttons.addBtn('Help').addBtn('Exit');
});

bot.start('localhost', 3000);
```

