import { BotController, WELCOME_INTENT_NAME } from 'umbot';

// The controller: adds the "Help" button to all responses and writes analytics
bot.initBotController(
    class extends BotController {
        // action() can also be async — the framework awaits the promise
        // before building the response.
        action(intentName: string | null, isCommand?: boolean, isStep?: boolean): void {
            // A shared button for all responses — written once
            this.buttons.addBtn('Help');

            // If a command/step fired, it has already filled text — exit
            if (isCommand || isStep) return;

            switch (intentName) {
                case WELCOME_INTENT_NAME:
                    // welcome_text has already been set by the framework —
                    // additionally count the user's visits
                    this.userData.visits = Number(this.userData.visits ?? 0) + 1;
                    break;
                default:
                    if (!this.text) this.text = 'I didn\'t get that. Say "help".';
            }

            // Analytics — fire-and-forget: the request goes in the background and does not block the response.
            // Always limit the time so that a slow analytics
            // endpoint does not "hang" the outgoing request forever.
            const ac = new AbortController();
            const timer = setTimeout(() => ac.abort(), 8000);
            timer.unref();
            fetch('https://analytics.example.com/event', {
                method: 'POST',
                signal: ac.signal,
                body: JSON.stringify({
                    intent: intentName,
                    platform: this.appType,
                    userId: this.userId,
                    isCommand,
                    isStep,
                }),
                headers: { 'Content-Type': 'application/json' },
            })
                .catch(() => {
                    // analytics errors must not affect the user
                })
                .finally(() => clearTimeout(timer));
        }
    },
);

// Commands describe specific logic
bot.use(gamePlugin);
bot.use(shopPlugin);
bot.addCommand('about', ['about us'], (_, bc) => {
    bc.text = '...';
});
