import { BotController, IUserData } from 'umbot';

interface PhoneData extends IUserData {
    phone?: string;
}

// A separate command — answers an "urgent" request during the scenario.
// It fires after the step, because step.cb returns false.
bot.addCommand('weather', ['weather'], async (userCommand, bc) => {
    const city = userCommand.replace('weather', '').trim() || 'moscow';
    const res = await fetch(`https://api.weather.example.com/current?city=${city}`, {
        signal: AbortSignal.timeout(3000), // the timeout is mandatory (see the anti-patterns)
    });
    const data = (await res.json()) as { temp: number };
    bc.text = `It is ${data.temp}°C now. `;
    // Restart the step explicitly: the command fired after the step returned false,
    // and thisIntentName is null by default. Without this line the scenario would end.
    bc.thisIntentName = 'ask_phone';
});

bot.addStep('ask_phone', (bc: BotController<PhoneData>) => {
    // Did the user send something that looks like the weather? Skip the step —
    // let the weather command above fire.
    if (bc.userCommand?.includes('weather')) {
        return false;
    }

    // Otherwise — regular step handling
    if (!bc.userCommand || bc.userCommand.length < 5) {
        bc.text = 'That does not look like a number. Enter your phone:';
        // IMPORTANT: thisIntentName is null by default — for the step to fire again,
        // it must be assigned again explicitly.
        bc.thisIntentName = 'ask_phone';
        return;
    }
    bc.userData.phone = bc.userCommand;
    bc.text = 'Done! The phone is saved.';
    bc.thisIntentName = null;
});
