import { BotController, IUserData } from 'umbot';

// Describe the userData type — it is used in the steps
interface RegData extends IUserData {
    name?: string;
    age?: number;
}

// Step 0: the trigger command that starts the scenario.
// userData is not touched here — no typing needed
bot.addCommand('register', ['register', 'sign up'], (_, bc) => {
    bc.text = 'What is your name?';
    bc.thisIntentName = 'reg_name'; // the next request goes to the reg_name step
});

// Step 1: waiting for the name — typed through the generic parameter
bot.addStep('reg_name', (bc: BotController<RegData>) => {
    if (!bc.userCommand || bc.userCommand.length < 2) {
        bc.text = 'The name is too short. Please try again.';
        // IMPORTANT: to stay on the step, thisIntentName must be reassigned explicitly —
        // in a new request it is null by default, and without the assignment the scenario ends
        bc.thisIntentName = 'reg_name';
        return;
    }
    bc.userData.name = bc.originalUserCommand ?? ''; // save it with the original case
    bc.text = `Nice to meet you, ${bc.userData.name}! How old are you?`;
    bc.thisIntentName = 'reg_age'; // go to the reg_age step
});

// Step 2: waiting for the age
bot.addStep('reg_age', (bc: BotController<RegData>) => {
    const age = parseInt(bc.userCommand || '', 10);
    if (isNaN(age) || age < 1 || age > 120) {
        bc.text = 'That does not look like an age. Enter a number from 1 to 120.';
        bc.thisIntentName = 'reg_age'; // stay on the step
        return;
    }
    bc.userData.age = age;
    bc.text = `Got it: you are ${age} years old. Registration is complete!`;
    bc.thisIntentName = null; // leave the scenario — the next request takes the regular path
});
