    nav = new Navigation<Product>(3); // 3 items per page

    public action(intentName: string | null): void {
        const products: Product[] = [
            { id: 1, name: 'Apple', price: 50 },
            { id: 2, name: 'Pear', price: 70 },
            { id: 3, name: 'Banana', price: 40 },
            { id: 4, name: 'Orange', price: 80 },
            { id: 5, name: 'Mango', price: 200 },
            { id: 6, name: 'Kiwi', price: 90 },
            { id: 7, name: 'Lemon', price: 30 },
        ];

        // Get the current page (the method itself moves thisPage on "дальше"/"назад" — "next"/"back")
        const page = this.nav.getPageElements(products, this.userCommand || '');

        // Render it as a list card
        this.card.setTitle('Choose a product');
        for (const p of page) {
            this.card.addImage(`https://shop.example.com/img/${p.id}.jpg`, p.name, `${p.price} ₽`, {
                title: 'Buy',
                payload: { action: 'buy', id: p.id },
            });
        }

        // Pagination buttons
        for (const caption of this.nav.getPageNav()) {
            this.buttons.addBtn(caption);
        }

        // Page information
        const info = this.nav.getPageInfo();
        if (info) this.buttons.addBtn(info);

        // Did the user choose an item?
        const selected = this.nav.selectedElement(products, this.userCommand || '', ['name']);
        if (selected) {
            this.text = `You chose: ${selected.name} for ${selected.price} ₽`;
        }
    }
}
```

